import { FormEvent, useState } from 'react';
import { JxButton, JxInputField, JxSelect, JxSwitch, JxToast } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'Только чтение' },
  { value: 'member', label: 'Участник', meta: 'Работа с задачами' },
  { value: 'admin', label: 'Администратор', meta: 'Полный доступ' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [invited, setInvited] = useState<string | null>(null);

  const trimmed = email.trim();
  const isValid = EMAIL_PATTERN.test(trimmed);
  const errorText =
    trimmed.length > 0 && !isValid ? 'Похоже, это не адрес почты. Например: anna@company.com' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) return;
    setInvited(trimmed);
    setEmail('');
  };

  const roleLabel = ROLES.find((option) => option.value === role)?.label ?? '';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px', maxWidth: '420px' }}>
      {invited ? (
        <JxToast
          variant="success"
          title="Приглашение отправлено"
          message={`${invited} получит доступ с ролью «${roleLabel}».`}
          onClose={() => setInvited(null)}
        />
      ) : null}

      <form onSubmit={submit} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }} noValidate>
        <JxInputField
          label="Почта участника"
          type="email"
          name="email"
          required
          autoComplete="email"
          placeholder="anna@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          helperText="Рабочий адрес — на него уйдёт ссылка-приглашение"
          errorText={errorText}
        />

        <JxSelect
          label="Роль в команде"
          options={ROLES}
          value={role}
          onValueChange={setRole}
          placeholder="Выберите роль"
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          name="notify"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <div style={{ display: 'flex', gap: '8px' }}>
          <JxButton type="submit" variant="primary" disabled={!isValid}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </div>
  );
}

